Translate("esES", "stonesplinter-troggs", {
	title = "Troggs Rompecantos",
	aliases = { "Rompecantos", "troggs Rompecantos", "tribu Rompecantos" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Rompecantos son los {link:troggs}troggs{/link} de {link:loch-modan}Loch Modan{/link}. Toman su nombre del {link:stonesplinter-valley}Valle Rompecantos{/link}, en el suroeste, y son el mayor peligro al que se enfrenta {link:the-loch}el lago{/link}. Ninguna crónica registra cuándo salieron por primera vez aquí de las profundidades.]=],
		},
		{
			title = "Sus tierras",
			text = [=[Dominan el {link:stonesplinter-valley}Valle Rompecantos{/link} y las colinas del sur, donde su cacique {link:grawmug}Grawmug{/link} ocupa la cueva más profunda. Se han apoderado de la isla más grande del lago. En la {link:ironband-s-excavation-site}Excavación de Vetaferro{/link}, donde surgieron entre las ruinas, un cacique llamado Galgosh y un chamán tribal llamado Magosh gobiernan la excavación. En sus filas hay exploradores, machacacráneos y rompehuesos, y videntes, chamanes y geomantes que obran una tosca magia de la tierra.]=],
		},
		{
			title = "En el presente",
			text = [=[Los Rompecantos se sienten atraídos por los ídolos tallados de la excavación, y algunos de ellos enloquecen a causa de los ídolos. El prospector {link:prospector-ironband}Ironband{/link} espera que algún día los ídolos expliquen el vínculo entre los troggs y los titanes. Hasta entonces, los montañeros de la torre del sur los combaten con lo poco que tienen. Cuentan los troggs que matan por sus dientes de piedra.]=],
		},
	},
})

Translate("esES", "mo-grosh-ogres", {
	title = "Ogros Mo'grosh",
	aliases = { "Mo'grosh", "ogros Mo'grosh", "clan Mo'grosh" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Mo'grosh son un clan de {link:ogres}ogros{/link} que se ha instalado en las cuevas de la {link:mo-grosh-stronghold}Fortaleza de Mo'grosh{/link}, en el noreste de {link:loch-modan}Loch Modan{/link}. Ninguna crónica registra de dónde vinieron ni cuándo se asentaron allí.]=],
		},
		{
			title = "Sus costumbres",
			text = [=[Son brutos, ejecutores y chamanes, con algunos místicos entre ellos, y siguen a un cacique llamado {link:chok-sul}Chok'sul{/link}. Extraen cristales en sus cuevas, tan raros que los enanos deben luchar por uno solo. Asaltan los caminos del lago, y se les culpa de los ataques contra {link:thelsamar}Thelsamar{/link}, la {link:stonewrought-dam}Presa de las Tres Cabezas{/link} y la excavación. Una vez tendieron una emboscada a una caravana de mineral que iba de {link:wetlands}Los Humedales{/link} a Thelsamar y se llevaron el mineral a su campamento.]=],
		},
		{
			title = "En el presente",
			text = [=[El magistrado de {link:thelsamar}Thelsamar{/link} ha contratado mercenarios para acabar con ellos, y hay precio sobre la cabeza de {link:chok-sul}Chok'sul{/link}. El magistrado quiere ocuparse primero de los ogros, para que el pueblo pueda por fin volverse contra los troggs.]=],
		},
	},
})

